<template>
  <div class="min-h-screen px-4 py-8 sm:px-6 lg:px-8"><div class="mx-auto max-w-[1500px] space-y-6">
    <PageHeader :title="t('admin_billing.organizations_title')" :description="t('admin_billing.organizations_desc')" />
    <div class="rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-white/10 dark:bg-white/5">
      <form class="grid gap-3 border-b border-slate-200 p-4 sm:grid-cols-2 lg:grid-cols-5 dark:border-white/10" @submit.prevent="applyFilters"><input v-model.trim="filters.search" class="billing-input lg:col-span-2" :placeholder="t('admin_billing.search_organization')" /><select v-model="filters.plan_type" class="billing-input"><option value="">{{ t('admin_billing.all_plans') }}</option><option v-for="plan in plans" :key="plan.id" :value="plan.code">{{ plan.name }}</option></select><select v-model="filters.plan_status" class="billing-input"><option value="">{{ t('admin_billing.all_plan_statuses') }}</option><option value="active">{{ t('admin_billing.active') }}</option><option value="expiring_soon">{{ t('admin_billing.status_expiring_soon') }}</option><option value="expired">{{ t('admin_billing.status_expired') }}</option></select><select v-model="filters.sort_direction" class="billing-input"><option value="asc">{{ t('admin_billing.expiry_near') }}</option><option value="desc">{{ t('admin_billing.expiry_far') }}</option></select><input v-model="filters.near_expiry_days" type="number" min="1" max="365" class="billing-input" :placeholder="t('admin_billing.near_expiry')" /><button class="rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-bold text-white dark:bg-white dark:text-slate-900">{{ t('admin_billing.filter') }}</button><button type="button" class="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-bold dark:border-white/10" @click="resetFilters">{{ t('admin_billing.clear_filters') }}</button></form>
      <PageState :loading="loading" :error="error" :empty="!organizations.length" :empty-text="t('admin_billing.no_organizations')" @retry="load"><div class="overflow-x-auto"><table class="min-w-full w-full text-left text-sm whitespace-nowrap"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-black/20 dark:text-slate-400"><tr><th class="p-4">{{ t('admin_billing.header_organization_owner') }}</th><th class="p-4">{{ t('admin_billing.header_plan') }}</th><th class="p-4">{{ t('admin_billing.header_start_expiry') }}</th><th class="p-4">{{ t('admin_billing.header_plan_status') }}</th><th class="p-4">{{ t('admin_billing.header_plan_tokens') }}</th><th class="p-4">{{ t('admin_billing.header_topup') }}</th><th class="p-4">{{ t('admin_billing.header_remaining') }}</th><th class="p-4">{{ t('admin_billing.header_used') }}</th><th class="p-4">{{ t('admin_billing.header_chatbot') }}</th><th class="p-4">{{ t('admin_billing.header_payment_latest') }}</th><th class="p-4 text-right">{{ t('admin_billing.header_actions') }}</th></tr></thead><tbody class="divide-y divide-slate-100 dark:divide-white/5"><tr v-for="org in organizations" :key="org.id"><td class="p-4"><p class="font-extrabold dark:text-white">{{ org.name }}</p><p class="text-xs text-slate-500">{{ org.owner?.name || '—' }} · {{ org.owner?.email || '—' }}</p></td><td class="p-4 font-bold uppercase">{{ org.plan_type }}</td><td class="p-4 whitespace-nowrap"><p>{{ formatBillingDate(org.plan_started_at) }}</p><p class="text-xs text-slate-500">{{ formatBillingDate(org.plan_expires_at) }}</p></td><td class="p-4"><StatusBadge :status="org.plan_status"/><p class="mt-1 text-xs text-slate-500">{{ org.days_remaining === null ? t('admin_billing.no_expiry') : `${org.days_remaining} ${t('admin_billing.days')}` }}</p></td><td class="p-4">{{ formatBillingLimit(org.plan_remaining_tokens) }}</td><td class="p-4">{{ formatBillingNumber(org.topup_tokens) }}</td><td class="p-4 font-bold">{{ formatBillingLimit(org.remaining_tokens) }}</td><td class="p-4">{{ formatBillingNumber(org.tokens_used) }}</td><td class="p-4">{{ formatBillingNumber(org.chatbots_count) }}</td><td class="p-4"><template v-if="org.latest_payment"><p class="font-mono text-xs">{{ org.latest_payment.order_code }}</p><p class="text-xs text-slate-500">{{ formatBillingMoney(org.latest_payment.amount, org.latest_payment.currency_snapshot || org.latest_payment.currency || 'VND') }} · {{ org.latest_payment.status }}</p></template><span v-else>—</span></td><td class="p-4 text-right"><NuxtLink :to="`/admin/billing/organizations/${org.id}`" class="inline-flex rounded-lg border border-slate-200 p-2 hover:border-cyan-400 hover:text-cyan-600 dark:border-white/10" :title="t('admin_billing.details')"><span class="material-symbols-outlined text-lg">visibility</span></NuxtLink></td></tr></tbody></table></div><Pagination :pagination="pagination" @change="changePage"/></PageState>
    </div>
  </div></div>
</template>

<script setup lang="ts">
import type { AdminBillingOrganization, BillingPagination, BillingPlan } from '~/types/admin-billing'; import PageHeader from '~/components/admin/billing/PageHeader.vue'; import PageState from '~/components/admin/billing/PageState.vue'; import Pagination from '~/components/admin/billing/Pagination.vue'; import StatusBadge from '~/components/admin/billing/StatusBadge.vue'; import { formatBillingDate, formatBillingLimit, formatBillingMoney, formatBillingNumber } from '~/utils/adminBilling'
const { t } = useI18n()
definePageMeta({ layout: 'layout-admin' }); const route = useRoute(); const api = useAdminBilling(); const organizations = ref<AdminBillingOrganization[]>([]); const plans = ref<BillingPlan[]>([]); const pagination = ref<BillingPagination>({ current_page: 1, per_page: 20, total: 0, last_page: 1 }); const defaults = () => ({ search: '', plan_type: '', plan_status: String(route.query.plan_status || ''), near_expiry_days: '', sort_direction: 'asc', page: 1, per_page: 20 }); const filters = reactive(defaults()); const loading = ref(true); const error = ref('')
const load = async () => { loading.value = true; error.value = ''; try { const response = await api.listOrganizations(filters); organizations.value = response.data; pagination.value = response.pagination } catch (e) { error.value = getAdminBillingErrorMessage(e) } finally { loading.value = false } }; const loadPlans = async () => { try { plans.value = (await api.listPlans({ per_page: 100 })).data } catch {} }; const applyFilters = () => { filters.page = 1; load() }; const resetFilters = () => { Object.assign(filters, defaults(), { plan_status: '' }); load() }; const changePage = (page: number) => { filters.page = page; load() }; onMounted(() => { load(); loadPlans() })
</script>
<style scoped>.billing-input{ @apply w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-cyan-500 dark:border-white/10 dark:bg-black/20 dark:text-white; }</style>
